import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.BDKIrnCI.js";const u=JSON.parse('{"title":"Port forwarding","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/port-forwarding.md"},"headers":[],"relativePath":"guides/port-forwarding.md","filePath":"docs/port-forwarding.md"}'),o={name:"guides/port-forwarding.md"};function n(r,e,d,h,l,p){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="port-forwarding" tabindex="-1">Port forwarding <a class="header-anchor" href="#port-forwarding" aria-label="Permalink to &quot;Port forwarding&quot;">​</a></h1><p>Players can only reach a server behind a home router when the router forwards the server&#39;s ports. This repo does that with UPnP and NAT-PMP, in layers that a plugin can use at the level it needs.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Package</th><th>What it is</th></tr></thead><tbody><tr><td>Engine</td><td><code>@pumpkin-plugins/port-mapping</code> (<code>tools/port-mapping</code>)</td><td>Finds the router and keeps ports open on it. No Pumpkin or WASI imports: it runs on a small <code>Network</code> interface, so it is unit-tested with a fake router.</td></tr><tr><td>Plugin</td><td>UPnPumpkin (<code>packages/upnpumpkin</code>)</td><td>Runs the engine on WASI sockets, opens the Java and Bedrock ports, and answers other plugins.</td></tr><tr><td>API</td><td><code>@pumpkin-plugins/upnpumpkin-api</code> (<code>tools/upnpumpkin-api</code>)</td><td>The messages, a client and a watcher for plugins that want a port opened.</td></tr><tr><td>Host</td><td><code>@pumpkin-plugins/plugin-kit</code> (<code>tools/plugin-kit</code>)</td><td>What every plugin needs from the host: data folder, logging, scheduling, commands, IPC.</td></tr></tbody></table><p>BedrockAddonManager is the first user of the API: it asks UPnPumpkin to open its web port when <code>web.public_url</code> is empty and <code>web.bind</code> is <code>0.0.0.0</code> (opt out with <code>web.port_forwarding = false</code>).</p><h2 id="how-the-engine-works" tabindex="-1">How the engine works <a class="header-anchor" href="#how-the-engine-works" aria-label="Permalink to &quot;How the engine works&quot;">​</a></h2><p>Plugins run inside a game tick and can&#39;t wait, so the engine is written as generators that yield while they wait for the network (<code>Steps&lt;T&gt;</code>, run by <code>Task</code>). <code>PortMapper</code> owns the work:</p><ol><li>If this machine&#39;s address toward the internet is public, nothing is opened.</li><li>Otherwise <code>discover</code> looks for a router: UPnP (an SSDP search, then the router&#39;s description and a SOAP <code>GetExternalIPAddress</code>) and NAT-PMP (a request to the first and last address of the local /24, or the gateway from the config) side by side. UPnP wins when both answer.</li><li>A router whose own internet-side address isn&#39;t public (carrier-grade NAT) is reported as a failure, because no mapping can make the server reachable through it.</li><li>Each requested port is opened with a lease, renewed at half the lease, moved to another public port when the router says the first is taken, and closed when released or when the plugin stops.</li><li>Failures are retried with growing waits (30 s up to 10 min), and the router is searched for again when an operation fails. Each failure is logged once, not on every retry; it is logged again after the port opened and later failed anew, or when the reason changes.</li></ol><h3 id="telling-routers-apart" tabindex="-1">Telling routers apart <a class="header-anchor" href="#telling-routers-apart" aria-label="Permalink to &quot;Telling routers apart&quot;">​</a></h3><p>Pass <code>screen</code> in the discovery options and the engine identifies routers before it asks them to do anything. The <code>screen</code> gets a <code>RouterIdentity</code> (manufacturer, model, model number, name) and returns a reason to turn the router down, or nothing. Turned down, a router is never used or asked again: the mapper&#39;s ports fail with the reason and <code>info().refused</code> is set. Without a <code>screen</code> nothing is identified. The order is:</p><ol><li>The router&#39;s web interface. Routers without UPnP or NAT-PMP can&#39;t describe themselves, so <code>identify.ts</code> has a short list of public pages that give them away (<code>WEB_FINGERPRINTS</code>: for now Telekom&#39;s Speedport login page). Only the first and last address of the local /24, or the configured NAT-PMP gateway, are asked, on port 80, with a short timeout.</li><li>UPnP devices: the SSDP search and the device description, whose <code>manufacturer</code>, <code>modelName</code>, <code>modelNumber</code> and <code>friendlyName</code> are the identity. No SOAP action is sent yet.</li><li>Only then the protocols themselves (the UPnP actions, NAT-PMP). NAT-PMP therefore waits for the UPnP search, which makes finding a router take up to the length of that search longer.</li></ol><p>NAT-PMP has no way to ask a router what it is, so a NAT-PMP-only router is only recognized by its web interface. A router that says nothing about itself is never turned down.</p><p>UPnPumpkin&#39;s <code>screen</code> is its blocklist, see below.</p><p>WASI has no way to list interfaces, read the routing table or join a multicast group, so the engine only needs two things from the host: an outgoing address toward a destination (a UDP socket pointed at it, which sends nothing) and sockets. That is the whole <code>Network</code> interface.</p><h2 id="the-blocklist" tabindex="-1">The blocklist <a class="header-anchor" href="#the-blocklist" aria-label="Permalink to &quot;The blocklist&quot;">​</a></h2><p><code>packages/upnpumpkin/src/blocklist.ts</code> lists the routers UPnPumpkin stays away from: a whole make (Telekom, which has no UPnP or NAT-PMP at all) or only some models. A rule has a <code>manufacturer</code> pattern, optional <code>models</code> and a short <code>reason</code>; a rule with models only blocks routers whose model is known. When the router is on the list:</p><ul><li>the log gets one warning, when the router has been identified (a few seconds after the start),</li><li><code>/upnp reload</code> fails with the same text,</li><li><code>/upnp status</code> shows it in red,</li><li>ports other plugins ask for fail with the reason.</li></ul><p>The README table of blocked routers is generated from the list (<code>info.blocks.routers</code>, see <a href="./plugin-info-and-readmes">Plugin info and READMEs</a>), so adding a rule updates the document with <code>pnpm readme</code>.</p><h2 id="asking-upnpumpkin-for-a-port" tabindex="-1">Asking UPnPumpkin for a port <a class="header-anchor" href="#asking-upnpumpkin-for-a-port" aria-label="Permalink to &quot;Asking UPnPumpkin for a port&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ipcSend } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pumpkin-plugins/plugin-kit/ipc&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { MappingWatcher, openUrl, PortMapClient } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pumpkin-plugins/upnpumpkin-api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> watcher</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MappingWatcher</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PortMapClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ipcSend), request, onChange, Date.now);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">watcher.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Call <code>watcher.tick()</code> once per game tick and <code>watcher.stop()</code> when done. Messages are JSON in Pumpkin&#39;s plugin messages (<code>ensure</code>, <code>status</code>, <code>release</code>, <code>info</code>; see <code>protocol.ts</code>). <code>ensure</code> is idempotent, so the watcher repeats it to learn how the request is going. UPnPumpkin keeps each plugin&#39;s keys apart, limits how many ports plugins may hold, and drops a request nobody has repeated for five minutes.</p><p>UPnPumpkin is optional for the plugin that asks: while it is missing the state is <code>unavailable</code> and the plugin carries on. Don&#39;t list it in <code>dependencies</code>, which would stop your plugin loading without it.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li>Engine and API: unit tests with <code>FakeNetwork</code> and <code>FakeIgd</code> from <code>@pumpkin-plugins/port-mapping/testing</code>, which move a clock by hand and simulate a router (UPnP and NAT-PMP, taken ports, permanent-lease-only routers, CGNAT).</li><li>UPnPumpkin: integration tests start a real server and a router on localhost (<code>@pumpkin-plugins/port-mapping/testing/router</code>: the same <code>FakeIgd</code> behind real UDP and HTTP sockets) and point the plugin at it with <code>router.upnp_search</code> and <code>router.nat_pmp_gateway</code>.</li><li>BedrockAddonManager with UPnPumpkin: <code>test/forwarding.itest.ts</code> loads both on one server (see <a href="./testing">Testing</a>).</li></ul>`,23)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
